<?php
require __DIR__.'/../includes/modules.php';$user=require_role('employee');$error='';$edit=[];
if(isset($_GET['edit'])){$edit=query_rows("SELECT * FROM leave_requests WHERE id=? AND employee_id=? AND status='Pending'",[record_id($_GET['edit']),$user['id']])[0]??null;if(!$edit)missing();}
if(post()){check_csrf();try{$id=empty($_POST['id'])?null:record_id($_POST['id']);$action=$_POST['action']??'';db()->beginTransaction();if($id&&!query_rows("SELECT id FROM leave_requests WHERE id=? AND employee_id=? AND status='Pending' FOR UPDATE",[$id,$user['id']])){db()->rollBack();missing();}
if($action==='delete'){if(!$id)throw new InvalidArgumentException('Choose a leave request.');execute_sql("DELETE FROM leave_requests WHERE id=? AND employee_id=? AND status='Pending'",[$id,$user['id']]);}
elseif($action==='save'){$type=choice('leave_type',['Casual','Sick','Annual','Other']);$start=date_value('start_date');$end=date_value('end_date');$reason=text_value('reason',2000);if($end<$start)throw new InvalidArgumentException('End date must be on or after start date.');$overlap=query_rows("SELECT id FROM leave_requests WHERE employee_id=? AND status IN ('Pending','Approved') AND start_date<=? AND end_date>=? AND id<>?",[$user['id'],$end,$start,$id??0]);if($overlap)throw new InvalidArgumentException('Dates overlap an existing pending or approved request.');if($id)execute_sql("UPDATE leave_requests SET leave_type=?,start_date=?,end_date=?,reason=? WHERE id=? AND employee_id=? AND status='Pending'",[$type,$start,$end,$reason,$id,$user['id']]);else execute_sql('INSERT INTO leave_requests (employee_id,leave_type,start_date,end_date,reason) VALUES (?,?,?,?,?)',[$user['id'],$type,$start,$end,$reason]);}
else throw new InvalidArgumentException('Invalid action.');db()->commit();flash('Leave request saved.');redirect('employee/leave.php');}catch(InvalidArgumentException $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();$edit=$_POST;}}
page_start('My Leave',$user);error_notice($error);?><section class="card"><h2>Apply / Edit Leave</h2><p>Pending requests can be edited or deleted. Approved and rejected requests remain in your history.</p><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><div class="form-grid"><?php select_field('leave_type','Leave type',options(['Casual','Sick','Annual','Other']),$edit['leave_type']??'');input_field('start_date','Start date',$edit['start_date']??'','date');input_field('end_date','End date',$edit['end_date']??'','date');input_field('reason','Reason',$edit['reason']??'');?></div><div class="actions"><button class="btn btn-primary" name="action" value="save">Submit Request</button><a class="btn btn-secondary" href="leave.php">Cancel</a></div></form></section><?php require __DIR__.'/../includes/leave-list.php';page_end();
